// ---- Badges in Canva: copy page 2 of "ID BADGE" (the blank designee template), fill name / org / next Agent ID; PNG export for the Badgy printer
const BADGE_TPL="DAHXv-hWPdQ", BADGE_TPL_PAGE=12, BADGE_TPL_PAGE_H=0, BADGE_ID_FLOOR=10;
// " ID BADGE" after the 10/11 restore — 13 pages. Page 12 is the only blank template (vertical, 204×324);
// every horizontal page is somebody's badge, so BADGE_TPL_PAGE_H=0 means "there isn't one".
//   1 Sheree Taylor · 2 Charlotte Parker · 3 Christina Castillo   (vertical)
//   4 Susan Sams #0004 · 5 Melysa Niebrugge #0005 · 6 Clarke Christiansen #0006
//   7 William Klee #0007 · 8 LaToya Brown #0008 · 9 Melissa Robinson #0009   (horizontal)
//  10 blank 1280×720 · 11 Ernest Moss #0010 · 12 BLANK VERTICAL TEMPLATE · 13 LaToya Brown #0008 (vertical)
// Page numbers move whenever a page is added or removed, so verify before trusting them.
const BADGE_ART={v:"data:image/jpeg;base64,",h:"data:image/jpeg;base64,"};   // snapshot of " ID BADGE" p.13 + p.4 so the preview draws instantly offline
// Agent IDs only ever go up — the high-water mark is kept in S.rules so deleting a badge never hands the same number to the next person.
function nextAgentId(){ return Math.max(BADGE_ID_FLOOR,+((S.rules||{}).lastAgentId)||0,...(S.badges||[]).map(b=>+b.agentId||0))+1; }
function claimAgentId(n){ if(!(+n>0)) return; if(+n>(+((S.rules||{}).lastAgentId)||0)){ S.rules=S.rules||{}; S.rules.lastAgentId=+n; rulesSave(); } }
// The saved link can be empty or stale, which is what made the Canva button land on a broken page.
// Ask Canva where the badge is right now, then open that.
const canvaOk=u=>/^https:\/\/(www\.)?canva\.com\/(d\/[A-Za-z0-9_-]{6,}|design\/[^\/]+\/[^\/]+)/.test(String(u||""));
async function canvaEditUrl(designId){ if(!designId||!S.mcp) return "";
  try{ const r=mcpPayload(await S.mcp.callTool(CANVA,"read-design",{design_id:designId,filter:{fields:["design_metadata"]},user_intent:"Find where this badge lives in Canva"},{cache:false}));
    const m=r.design_metadata||r.design||r; return (m.urls&&m.urls.edit_url)||(m.urls&&m.urls.view_url)||(JSON.stringify(r).match(/https:\/\/(?:www\.)?canva\.com\/(?:d|design)\/[^"\s]+/)||[])[0]||"";
  }catch(_){ return ""; } }
function openTab(u){ let w=null; try{ w=window.open(u,"_blank"); if(w) w.opener=null; }catch(_){ } if(!w){ copyText(u); toast("Link copied \u2014 paste it in your browser"); } }
const CANVA_URL_SEEN={};   // resolved this session; a stored link may point at a design that no longer exists
async function badgeOpen(bd,btn){
  if(CANVA_URL_SEEN[bd.id]){ openTab(CANVA_URL_SEEN[bd.id]); return; }
  if(!S.mcp){ if(canvaOk(bd.canvaUrl)) openTab(bd.canvaUrl); else toast("Open this page in claude.ai with Canva connected"); return; }
  const lbl=btn&&btn.textContent; if(btn){ btn.disabled=true; btn.textContent="⏳ Finding…"; }
  try{
    let u=await canvaEditUrl(bd.canvaId), onMaster=false;          // their own badge design, if it still exists
    if(!canvaOk(u)){ u=await canvaEditUrl(BADGE_TPL); onMaster=true; }   // otherwise it lives as a page inside ID BADGE
    if(!canvaOk(u)){
      toast("Canva can't find that badge any more — tap \u{1F3A8} Make in Canva to rebuild it");
      if(bd.canvaUrl){ try{ await bgcol().doc(bd.id).update({canvaUrl:""}); }catch(_){ } bd.canvaUrl=""; S.badges=(S.badges||[]).map(z=>z.id===bd.id?{...z,canvaUrl:""}:z); renderList(); }
      return; }
    CANVA_URL_SEEN[bd.id]=u;
    if(u!==bd.canvaUrl){ try{ await bgcol().doc(bd.id).update({canvaUrl:u}); }catch(_){ } bd.canvaUrl=u; S.badges=(S.badges||[]).map(z=>z.id===bd.id?{...z,canvaUrl:u}:z); }
    if(onMaster&&bd.masterPage) toast("Opening ID BADGE — scroll to page "+bd.masterPage);
    openTab(u);
  } finally { if(btn){ btn.disabled=false; btn.textContent=lbl; } } }
async function badgeCanva(bd,btn){ if(!S.mcp){ toast("Needs Canva connected in claude.ai"); return null; } if(bd.canvaUrl) return bd.canvaUrl;
  const id4=bd.agentId||nextAgentId(), org=bd.org||"", title=`Badge — ${bd.name}${org?" ("+org+")":""}`; if(btn){ btn.disabled=true; btn.textContent="🪄 Making…"; }
  let tx=null; try{
    const c=mcpPayload(await S.mcp.callTool(CANVA,"copy-design",{design_id:BADGE_TPL,page_numbers:[BADGE_TPL_PAGE],user_intent:"Make the designee badge for "+bd.name},{cache:false})); const des=c.design||c; if(!des.id) throw {message:"Canva didn't return the badge."};
    const url=(des.urls&&des.urls.edit_url)||"";
    const rd=mcpPayload(await S.mcp.callTool(CANVA,"read-design",{design_id:des.id,open_transaction:true,filter:{fields:["design_content"]},user_intent:"Fill the badge for "+bd.name},{cache:false})); tx=rd.transaction&&rd.transaction.transaction_id; const pg=((rd.design_content&&rd.design_content.pages)||[])[0]; if(!tx||!pg) throw {message:"Canva didn't open the badge for editing."};
    const rep={"First Name & Last Name":bd.name,"Agent ID #0000":"Agent ID #"+String(id4).padStart(4,"0")}; if(org) rep["Company Logo"]=org;
    const ops=[{type:"update_title",title}]; (pg.elements||[]).forEach(el=>{ if(el.type!=="text") return; const txt=(el.textRegions||[]).map(r=>r.characters||"").join(""); Object.keys(rep).forEach(k=>{ if(txt.includes(k)){ ops.push({type:"find_and_replace_text",locator_id:el.locator_id,find_text:k,replace_text:rep[k]}); if(k==="Company Logo"&&org.length>14) ops.push({type:"format_text",locator_id:el.locator_id,formatting:{font_size:org.length>26?10:11}}); } }); });
    await S.mcp.callTool(CANVA,"edit-design",{transaction_id:tx,page_index:1,finalize:"keep_open",operations:ops,user_intent:"Fill the badge"},{cache:false});
    await S.mcp.callTool(CANVA,"edit-design",{transaction_id:tx,finalize:"commit",user_intent:"Save the badge"},{cache:false}); tx=null;
    // file it as a page inside the ID BADGE design (where Sheree edits), keep the copy id for photo/logo placement
    const master=null;   // badges are kept as their own designs — nothing is written into ID BADGE
    const openUrl=master&&master.url?master.url:url;
    bd.canvaUrl=openUrl; bd.canvaId=des.id; bd.agentId=id4; claimAgentId(id4); if(master) bd.masterPage=master.page; await bgcol().doc(bd.id).update({canvaUrl:openUrl,canvaId:des.id,copyUrl:url,masterPage:master?master.page:null,agentId:id4,madeAt:new Date().toISOString()});
    toast(master?"🎨 Badge is page "+master.page+" of ID BADGE in Canva":"🎨 Badge ready in Canva"); try{ kCheer("badge"); }catch(_){ } agLog("Made badge in Canva: "+bd.name+" #"+String(id4).padStart(4,"0"),{act:"badge",ref:bd.id}); return openUrl||url;
  }catch(e){ if(tx){ try{ await S.mcp.callTool(CANVA,"edit-design",{transaction_id:tx,finalize:"cancel",user_intent:"Discard"},{cache:false}); }catch(_){ } } toast(e&&e.code==="not_in_manifest"||e&&e.code==="not_granted"?"Allow Canva for this page (Permissions menu), then try again":"Couldn't make the badge: "+((e&&e.message)||"try again")); if(btn){ btn.disabled=false; btn.textContent="🎨 Make in Canva"; } return null; } }
async function badgePng(bd,btn){ if(!S.mcp||!bd.canvaId){ toast("Make it in Canva first"); return; } if(btn){ btn.disabled=true; btn.textContent="⏳"; }
  try{ const r=mcpPayload(await S.mcp.callTool(CANVA,"export-design",{design_id:bd.canvaId,format:{type:"png"},user_intent:"Print-ready PNG for the Badgy printer"},{cache:false})); const job=r.job||r; const url=(job.urls&&job.urls[0])||(JSON.stringify(r).match(/https:\/\/[^"\s]+\.png[^"\s]*/)||[])[0];
    if(!url) throw {message:"Canva is still exporting — try again in a few seconds."}; let w=null; try{ w=window.open(url,"_blank"); if(w) w.opener=null; }catch(_){} if(!w){ await copyText(url); toast("PNG link copied — paste it in your browser"); } else toast("🖨️ PNG opened — print it on the Badgy");
    if((bd.status||"Needed")==="Needed") await bgcol().doc(bd.id).update({status:"Made",madeAt:new Date().toISOString()});
  }catch(e){ toast((e&&e.message)||"Couldn't export"); } finally{ if(btn){ btn.disabled=false; btn.textContent="🖨️ PNG"; } } }
// ---- Badge photo + logo, agent-run: file → Google Drive (shared folder) → Canva import → Canva remove-background → placed on the badge → saved
const DRIVE="Google Drive", BADGE_DRIVE_FOLDER="1t_TpOdUtkJZ3FQA1BtT3U31_fsCuiSrj";   // "Workstream Badge Uploads" — must be shared "Anyone with the link" once so Canva can fetch from it
const BADGE_BOX={vertical:{photo:{top:114.5,left:54.5,w:95,h:95},logo:{top:8,left:42,w:120}},horizontal:{photo:{top:47,left:35,w:110,h:110},logo:{top:11,left:185.5,w:99}}};   // measured off " ID BADGE": p.13 vertical (204×324), p.4 horizontal (324×204)
function fileB64(f){ return new Promise((ok,no)=>{ const r=new FileReader(); r.onload=()=>ok(String(r.result).split(",")[1]); r.onerror=()=>no(r.error||{message:"couldn't read the file"}); r.readAsDataURL(f); }); }
function idOf(o){ if(!o) return ""; if(typeof o==="string") return o; if(Array.isArray(o)) return idOf(o[0]); return o.media_id||o.asset_id||o.id||idOf(o.results)||idOf(o.job&&o.job.asset)||idOf(o.media)||idOf(o.asset)||idOf(o.result)||idOf(o.image)||idOf(o.content)||""; }
async function driveShare(file,title){ const b64=file&&file.b64?file.b64:await fileB64(file); const mime=(file&&(file.mime||file.type))||"image/png"; let r; try{ r=mcpPayload(await S.mcp.callTool(DRIVE,"create_file",{title,contentMimeType:mime,base64Content:b64,parentId:BADGE_DRIVE_FOLDER,disableConversionToGoogleType:true},{cache:false})); }catch(e){ if(e&&(e.code==="not_in_manifest"||e.code==="not_granted")) throw e; throw {message:"Google Drive: "+((e&&(e.message||e.code))||"no reply")}; } const id=r.id||(r.file&&r.file.id); if(!id) throw {message:"Google Drive didn't take the file."}; return {id,url:"https://lh3.googleusercontent.com/d/"+id}; }   // direct-200 form; drive.google.com/uc redirects and Canva refuses redirects
async function canvaImport(url,name){ const r=mcpPayload(await S.mcp.callTool(CANVA,"upload-asset-from-url",{url,name,user_intent:"Import "+name+" for the badge"},{cache:false})); const id=idOf(r); if(!id) throw {message:"Canva couldn't fetch it — share the 'Workstream Badge Uploads' Drive folder as Anyone with the link, then retry."}; return id; }
async function canvaCutout(mediaId){ try{ const r=mcpPayload(await S.mcp.callTool(CANVA,"remove-background",{sourceMedia:{type:"MEDIA",id:mediaId},user_intent:"Cut the background out of the badge photo"},{cache:false})); return idOf(r)||mediaId; }catch(_){ return mediaId; } }
async function badgePlace(bd,kind,assetId){
  const rd=mcpPayload(await S.mcp.callTool(CANVA,"read-design",{design_id:bd.canvaId,open_transaction:true,filter:{fields:["design_content"]},user_intent:"Place the "+kind+" on the badge"},{cache:false})); const tx=rd.transaction&&rd.transaction.transaction_id; const pg=((rd.design_content&&rd.design_content.pages)||[])[0]; if(!tx||!pg) throw {message:"Canva didn't open the badge."};
  const txtOf=el=>(el.textRegions||[]).map(r=>r.characters||"").join(""); const ops=[];
  (pg.elements||[]).forEach(el=>{ if(el.type!=="text") return; const t=txtOf(el).trim(); if(kind==="photo"&&/^badge photo$/i.test(t)) ops.push({type:"delete_element",locator_id:el.locator_id}); if(kind==="logo"&&(t==="Company Logo"||(bd.org&&t===bd.org))) ops.push({type:"delete_element",locator_id:el.locator_id}); });
  const dim=pg.dimensions||{}; const lay=(dim.width||0)>(dim.height||0)?"horizontal":"vertical"; const box=BADGE_BOX[lay][kind]; const near=(el,b)=>el.fill&&el.fill.media&&Math.abs((el.top||0)-b.top)<12&&Math.abs((el.left||0)-b.left)<12&&Math.abs((el.width||0)-b.w)<14;
  const frame=(pg.elements||[]).find(el=>(el.type==="rect"||el.type==="image")&&near(el,box)&&!(el.fill.media.altText&&el.fill.media.altText.text));
  if(frame){ ops.push({type:"update_fill",locator_id:frame.locator_id,asset_type:"image",asset_id:assetId,alt_text:kind==="photo"?bd.name+" photo":(bd.org||"")+" logo"}); }
  else { const prev=(pg.elements||[]).find(el=>el.fill&&el.fill.media&&el.fill.media.altText&&String(el.fill.media.altText.text||"").endsWith(kind==="photo"?" photo":" logo")); if(prev) ops.push({type:"delete_element",locator_id:prev.locator_id});
    const o={type:"insert_fill",page_id:pg.id||pg.page_id||pg.locator_id,asset_type:"image",asset_id:assetId,alt_text:kind==="photo"?bd.name+" photo":(bd.org||"")+" logo",top:box.top,left:box.left,width:box.w}; if(box.h) o.height=box.h; ops.push(o); }
  try{ await S.mcp.callTool(CANVA,"edit-design",{transaction_id:tx,page_index:1,finalize:"keep_open",operations:ops,user_intent:"Place the "+kind},{cache:false}); await S.mcp.callTool(CANVA,"edit-design",{transaction_id:tx,finalize:"commit",user_intent:"Save the badge"},{cache:false}); }
  catch(e){ try{ await S.mcp.callTool(CANVA,"edit-design",{transaction_id:tx,finalize:"cancel",user_intent:"Discard"},{cache:false}); }catch(_){ } throw e; } }
function partnerLogoAsset(org){ const p=(S.partners||[]).find(x=>(x.org||x.name)===org); return (p&&p.logoAsset)||""; }
async function saveLogoAsset(org,assetId,driveId){ const p=(S.partners||[]).find(x=>(x.org||x.name)===org); if(!p) return; try{ await pcol().doc(p.id).update({logoAsset:assetId,logoDrive:driveId}); }catch(_){ } }
async function badgeAddImage(bd,kind,file,btn){ if(!S.mcp){ toast("Needs Canva + Google Drive connected in claude.ai"); return; } if(!file) return; const lbl=btn&&btn.textContent; const say=t=>{ if(btn){ btn.disabled=true; btn.textContent=t; } };
  let stepName="start"; const at=n=>{ stepName=n; say(n); };
  try{ if(file&&file.uri&&!file.b64){ at("📧 Email…"); const got=await mailImageB64(file.uri); file={b64:got.b64,mime:got.mime||file.mime,name:file.name||"photo.png"}; }
    { at("🖼️ Sizing…"); const b=file&&file.b64?file.b64:await fileB64(file); const sm=await shrinkB64(b,(file&&(file.mime||file.type))||"image/png",kind==="photo"?900:1200,kind==="photo"); file={b64:sm.b64,mime:sm.mime,name:(file&&file.name)||kind+".png"}; }
    if(!bd.canvaId){ at("🪄 Badge…"); if(!(await badgeCanva(bd,null))||!bd.canvaId) throw {message:"couldn't make the badge first"}; }
    let assetId=kind==="logo"?partnerLogoAsset(bd.org):"", driveId="";
    if(!assetId){ at("☁️ Drive…"); const d=await driveShare(file,(kind==="photo"?bd.name:(bd.org||"logo"))+" — badge "+kind+(/\.[a-z0-9]+$/i.test(file.name||"")?file.name.slice(file.name.lastIndexOf(".")):".png")); driveId=d.id;
      at("🎨 Canva…"); const mid=await canvaImport(d.url,(kind==="photo"?bd.name:(bd.org||""))+" badge "+kind);
      if(kind==="photo"){ at("✂️ Cutout…"); assetId=await canvaCutout(mid); } else { assetId=mid; if(bd.org) await saveLogoAsset(bd.org,assetId,driveId); } }
    at("📌 Placing…"); await badgePlace(bd,kind,assetId);
    await bgcol().doc(bd.id).update({[kind+"Asset"]:assetId,[kind+"Drive"]:driveId,[kind+"At"]:new Date().toISOString()});
    toast(kind==="photo"?"📷 Photo cut out and placed — 🖨️ PNG when ready":"🏢 Logo placed on the badge"); agLog("Placed "+kind+" on badge: "+bd.name,{act:"badge",ref:bd.id}); }
  catch(e){ const why=e&&(e.code==="not_in_manifest"||e.code==="not_granted")?"Allow Canva + Google Drive for this page (Permissions menu), then retry":((e&&e.message)||"try again"); toast("Stopped at "+stepName.replace("…","")+" — "+why); try{ agLog("Badge "+kind+" failed at "+stepName.replace("…","")+": "+why+" ("+bd.name+")",{act:"badge",ref:bd.id}); }catch(_){ } }
  finally{ if(btn){ btn.disabled=false; btn.textContent=lbl; } } }
// ---- Flyer in Canva, agent-run: copy "Generic Ambassador Flyer" → their name + phone on both pages → their link on page 2 → QR of their UTM link (made here, Drive → Canva) swapped into both QR slots → saved
const FLYER_TPL="DAHSNfiFn9U", FLYER_QR_MEDIA="MAHSXvDwlc4", FLYER_NAME="Sheree Taylor", FLYER_PHONE="(773) 322-2694", FLYER_LINK="ampion.net/trenton";
function qrPngFile(text,name){ return new Promise((ok,no)=>{ try{ const box=document.createElement("div"); box.style.cssText="position:fixed;left:-9999px;top:0"; document.body.appendChild(box); new QRCode(box,{text,width:720,height:720,correctLevel:QRCode.CorrectLevel.M});
    setTimeout(()=>{ const cv=box.querySelector("canvas"); if(!cv){ box.remove(); return no({message:"couldn't draw the QR code"}); }
      const out=document.createElement("canvas"); out.width=out.height=800; const g=out.getContext("2d"); g.fillStyle="#fff"; g.fillRect(0,0,800,800); g.drawImage(cv,40,40,720,720);   // quiet zone so it scans on print
      out.toBlob(b=>{ box.remove(); b?ok(new File([b],name,{type:"image/png"})):no({message:"couldn't draw the QR code"}); },"image/png"); },60); }catch(e){ no(e); } }); }
function linkShort(u){ return String(u||"").replace(/^https?:\/\/(www\.)?/,"").split("?")[0].replace(/\/+$/,""); }
async function flyerCanva(p,btn){ if(!S.mcp){ toast("Needs Canva + Google Drive connected in claude.ai"); return null; }
  // A flyer is only good for the link its QR was drawn from. If the link changed (or the referral code did), rebuild.
  const stale=p.flyerUrl&&String(p.flyerLink||"")!==String(p.utmLink||"");
  if(p.flyerUrl&&!stale&&!(btn&&btn.dataset.redo)) return p.flyerUrl;
  if(stale) toast("Their link changed \u2014 making a fresh flyer so the QR matches");
  const link=p.utmLink||""; if(!link){ toast("Make their tracked link first (🔗 step)"); return null; } const name=p.name||p.org||"", phone=p.phone||"", lbl=btn&&btn.textContent; const say=t=>{ if(btn){ btn.disabled=true; btn.textContent=t; } };
  let tx=null; try{
    say("📄 Copying…"); const c=mcpPayload(await S.mcp.callTool(CANVA,"copy-design",{design_id:FLYER_TPL,user_intent:"Make the flyer for "+name},{cache:false})); const des=c.design||c; if(!des.id) throw {message:"Canva didn't return the flyer."}; const url=(des.urls&&des.urls.edit_url)||"";
    say("▦ QR…"); const qf=await qrPngFile(link,name.replace(/[^\w]+/g,"_")+"_QR.png"); say("☁️ Drive…"); const d=await driveShare(qf,name+" — flyer QR.png"); say("🎨 Canva…"); const qrAsset=await canvaImport(d.url,name+" QR code");
    say("✏️ Filling…"); const rd=mcpPayload(await S.mcp.callTool(CANVA,"read-design",{design_id:des.id,open_transaction:true,filter:{fields:["design_content"]},user_intent:"Fill the flyer for "+name},{cache:false})); tx=rd.transaction&&rd.transaction.transaction_id; const pgs=(rd.design_content&&rd.design_content.pages)||[]; if(!tx||!pgs.length) throw {message:"Canva didn't open the flyer for editing."};
    const txtOf=el=>(el.textRegions||[]).map(r=>r.characters||"").join("");
    let qrSlots=0;
    for(let i=0;i<pgs.length;i++){ const ops=i===0?[{type:"update_title",title:"Flyer — "+name}]:[]; (pgs[i].elements||[]).forEach(el=>{
        if(el.type==="text"){ const t=txtOf(el); if(t.includes(FLYER_NAME)) ops.push({type:"find_and_replace_text",locator_id:el.locator_id,find_text:FLYER_NAME,replace_text:name}); if(t.includes(FLYER_PHONE)) ops.push({type:"find_and_replace_text",locator_id:el.locator_id,find_text:FLYER_PHONE,replace_text:phone||"Dimension Energy"}); // Page 2 carries the FULL tracked link, so a person who types it instead of scanning the QR still counts as their referral.
          const shown=i===1?link.replace(/^https?:\/\//,""):linkShort(link);
          if(t.includes("https://"+FLYER_LINK)) ops.push({type:"find_and_replace_text",locator_id:el.locator_id,find_text:"https://"+FLYER_LINK,replace_text:shown}); else if(t.includes(FLYER_LINK)) ops.push({type:"find_and_replace_text",locator_id:el.locator_id,find_text:FLYER_LINK,replace_text:shown});
          if(i===1&&t.includes(FLYER_LINK)) ops.push({type:"format_text",locator_id:el.locator_id,formatting:{font_size:11,text_align:"center",line_height:1.25}}); }
        const mid=el.fill&&el.fill.media&&el.fill.media.mediaId; if(mid===FLYER_QR_MEDIA){ qrSlots++; ops.push({type:"update_fill",locator_id:el.locator_id,asset_type:"image",asset_id:qrAsset,alt_text:"QR code — "+name+"'s sign-up link"}); } });
      if(ops.length) await S.mcp.callTool(CANVA,"edit-design",{transaction_id:tx,page_index:i+1,finalize:"keep_open",operations:ops,user_intent:"Fill the flyer page "+(i+1)},{cache:false}); }
    if(!qrSlots) throw {message:"couldn't find the QR code on the flyer template — tell Claude, the template's QR image changed"};
    await S.mcp.callTool(CANVA,"edit-design",{transaction_id:tx,finalize:"commit",user_intent:"Save the flyer"},{cache:false}); tx=null;
    try{ if(p.id) await pcol().doc(p.id).update({flyerUrl:url,flyerId:des.id,flyerQr:qrAsset,flyerLink:link,kit:{...(p.kit||{}),flyer:true}}); }catch(_){ } p.flyerUrl=url; p.flyerId=des.id; p.flyerLink=link; p.kit={...(p.kit||{}),flyer:true};
    toast("📄 Flyer ready — "+qrSlots+" QR code"+(qrSlots===1?"":"s")+" pointing at "+(p.refCode?"code "+p.refCode:"their link")); agLog("Made flyer in Canva: "+name,{act:"flyer",ref:p.id}); return url;
  }catch(e){ if(tx){ try{ await S.mcp.callTool(CANVA,"edit-design",{transaction_id:tx,finalize:"cancel",user_intent:"Discard"},{cache:false}); }catch(_){ } } const why=e&&(e.code==="not_in_manifest"||e.code==="not_granted")?"Allow Canva + Google Drive for this page (Permissions menu), then retry":((e&&e.message)||"try again"); toast("Flyer stopped — "+why); try{ agLog("Flyer failed for "+name+": "+why,{act:"flyer",ref:p.id}); }catch(_){ } return null; }
  finally{ if(btn){ btn.disabled=false; btn.textContent=lbl; } } }
// ---- Badge pipeline self-test: proves each hop and writes the result to the agent log so it can be read from a chat session
const TEST_PNG="iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNk+M9QDwADhgGAWjR9awAAAABJRU5ErkJggg==";
async function badgeSelfTest(btn){ const out=[]; const say=(k,ok,d)=>{ out.push((ok?"✅ ":"❌ ")+k+(d?" — "+d:"")); const el=$("bdgTest"); if(el){ el.hidden=false; el.textContent=out.join("\n"); } };
  if(btn){ btn.disabled=true; btn.textContent="🧪 Testing…"; }
  say("Page version",true,"build 113");
  if(!S.mcp){ say("Connectors",false,"window.claude.mcp missing — open this page inside claude.ai (not a copy) and allow connectors"); }
  else {
    try{ const r=mcpPayload(await S.mcp.callTool(CANVA,"read-design",{design_id:BADGE_TPL,filter:{fields:["design_metadata"]},user_intent:"Connection test"},{cache:false})); say("Canva",true,(r.design_metadata&&r.design_metadata.title)||(r.title)||"ok"); }
    catch(e){ say("Canva",false,(e&&(e.code||""))+" "+(e&&e.message||"")); }
    let driveId="";
    try{ const r=mcpPayload(await S.mcp.callTool(DRIVE,"create_file",{title:"workstream-test.png",contentMimeType:"image/png",base64Content:TEST_PNG,parentId:BADGE_DRIVE_FOLDER,disableConversionToGoogleType:true},{cache:false})); driveId=r.id||(r.file&&r.file.id)||""; say("Google Drive",!!driveId,driveId?"file "+driveId:JSON.stringify(r).slice(0,160)); }
    catch(e){ say("Google Drive",false,(e&&(e.code||""))+" "+(e&&e.message||"")); }
    if(driveId){ try{ const id=await canvaImport("https://lh3.googleusercontent.com/d/"+driveId,"workstream test"); say("Drive → Canva import",true,"asset "+id); }catch(e){ say("Drive → Canva import",false,(e&&(e.code||""))+" "+(e&&e.message||"")); } }
  }
  say("QR library",typeof QRCode!=="undefined",typeof QRCode!=="undefined"?"loaded":"blocked");
  try{ await agLog("Badge self-test: "+out.join(" | "),{act:"badge"}); }catch(_){ }
  if(btn){ btn.disabled=false; btn.textContent="🧪 Test connections"; } }
window.Workstream.flyer={make:flyerCanva}; window.Workstream.badgeTest=badgeSelfTest;